-- SENTINEL AI database schema
-- Version 1: initial schema
-- All identifiers are generated by the application.

CREATE TABLE users (
    id TEXT PRIMARY KEY,
    username TEXT NOT NULL COLLATE NOCASE UNIQUE
        CHECK (length(trim(username)) BETWEEN 3 AND 64),
    email TEXT COLLATE NOCASE UNIQUE,
    password_hash TEXT NOT NULL
        CHECK (length(password_hash) >= 20),
    is_active INTEGER NOT NULL DEFAULT 1
        CHECK (is_active IN (0, 1)),
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL
);

CREATE TABLE roles (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    description TEXT
);

CREATE TABLE permissions (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL UNIQUE,
    description TEXT
);

CREATE TABLE user_roles (
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    PRIMARY KEY (user_id, role_id)
);

CREATE TABLE role_permissions (
    role_id TEXT NOT NULL REFERENCES roles(id) ON DELETE CASCADE,
    permission_id TEXT NOT NULL REFERENCES permissions(id) ON DELETE CASCADE,
    PRIMARY KEY (role_id, permission_id)
);

CREATE TABLE user_sessions (
    id TEXT PRIMARY KEY,
    user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_hash TEXT NOT NULL UNIQUE
        CHECK (
            length(token_hash) = 64
            AND token_hash NOT GLOB '*[^0-9a-f]*'
        ),
    created_at TEXT NOT NULL,
    expires_at TEXT NOT NULL,
    revoked_at TEXT
);

CREATE TABLE target_profiles (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    target_type TEXT NOT NULL
        CHECK (target_type IN ('vulnerable', 'secure')),
    security_mode TEXT NOT NULL CHECK (length(trim(security_mode)) > 0),
    is_enabled INTEGER NOT NULL DEFAULT 0
        CHECK (is_enabled IN (0, 1)),
    created_at TEXT NOT NULL
);

CREATE TABLE model_profiles (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    provider_type TEXT NOT NULL,
    model_identifier TEXT,
    configuration_json TEXT,
    created_at TEXT NOT NULL
);

CREATE TABLE test_cases (
    id TEXT PRIMARY KEY,
    scenario_code TEXT NOT NULL UNIQUE
        CHECK (scenario_code GLOB 'AI-[0-9][0-9][0-9]'),
    name TEXT NOT NULL,
    category TEXT NOT NULL,
    objective TEXT NOT NULL,
    expected_behavior TEXT NOT NULL,
    severity_default TEXT
        CHECK (
            severity_default IS NULL OR severity_default IN
            ('critical', 'high', 'medium', 'low', 'informational')
        ),
    framework_mapping_json TEXT,
    is_enabled INTEGER NOT NULL DEFAULT 1
        CHECK (is_enabled IN (0, 1)),
    version TEXT NOT NULL
);

CREATE TABLE assessments (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT,
    target_profile_id TEXT NOT NULL
        REFERENCES target_profiles(id) ON DELETE RESTRICT,
    model_profile_id TEXT NOT NULL
        REFERENCES model_profiles(id) ON DELETE RESTRICT,
    status TEXT NOT NULL
        CHECK (status IN
            ('draft', 'queued', 'running', 'completed', 'failed', 'cancelled')),
    created_at TEXT NOT NULL,
    started_at TEXT,
    completed_at TEXT
);

CREATE TABLE test_runs (
    id TEXT PRIMARY KEY,
    assessment_id TEXT NOT NULL
        REFERENCES assessments(id) ON DELETE RESTRICT,
    test_case_id TEXT NOT NULL
        REFERENCES test_cases(id) ON DELETE RESTRICT,
    status TEXT NOT NULL
        CHECK (status IN
            ('queued', 'running', 'completed', 'failed', 'cancelled')),
    started_at TEXT,
    completed_at TEXT,
    execution_result TEXT,
    error_summary TEXT
);

CREATE TABLE findings (
    id TEXT PRIMARY KEY,
    test_run_id TEXT NOT NULL
        REFERENCES test_runs(id) ON DELETE RESTRICT,
    title TEXT NOT NULL,
    description TEXT NOT NULL,
    severity TEXT NOT NULL
        CHECK (severity IN
            ('critical', 'high', 'medium', 'low', 'informational')),
    confidence TEXT NOT NULL
        CHECK (confidence IN ('high', 'medium', 'low')),
    risk_score REAL
        CHECK (risk_score IS NULL OR risk_score BETWEEN 0 AND 100),
    status TEXT NOT NULL DEFAULT 'open'
        CHECK (status IN
            ('open', 'confirmed', 'mitigated', 'accepted', 'false_positive')),
    mitigation TEXT,
    created_at TEXT NOT NULL
);

CREATE TABLE evidence (
    id TEXT PRIMARY KEY,
    test_run_id TEXT NOT NULL
        REFERENCES test_runs(id) ON DELETE RESTRICT,
    finding_id TEXT REFERENCES findings(id) ON DELETE RESTRICT,
    evidence_type TEXT NOT NULL,
    storage_path TEXT NOT NULL CHECK (length(trim(storage_path)) > 0),
    sha256 TEXT NOT NULL
        CHECK (
            length(sha256) = 64
            AND sha256 NOT GLOB '*[^0-9a-f]*'
        ),
    content_size INTEGER
        CHECK (content_size IS NULL OR content_size >= 0),
    classification TEXT NOT NULL
        CHECK (classification IN
            ('synthetic_public', 'synthetic_internal', 'synthetic_confidential')),
    collected_at TEXT NOT NULL
);

CREATE TABLE security_events (
    id TEXT PRIMARY KEY,
    assessment_id TEXT REFERENCES assessments(id) ON DELETE RESTRICT,
    test_run_id TEXT REFERENCES test_runs(id) ON DELETE RESTRICT,
    event_type TEXT NOT NULL,
    severity TEXT NOT NULL
        CHECK (severity IN
            ('critical', 'high', 'medium', 'low', 'informational')),
    description TEXT NOT NULL,
    created_at TEXT NOT NULL
);

CREATE TABLE audit_log (
    id TEXT PRIMARY KEY,
    user_id TEXT REFERENCES users(id) ON DELETE RESTRICT,
    action TEXT NOT NULL,
    resource_type TEXT NOT NULL,
    resource_id TEXT,
    outcome TEXT NOT NULL,
    created_at TEXT NOT NULL
);

-- Append-only protection against ordinary UPDATE and DELETE statements.
-- This does not protect against someone who can modify the database file
-- or drop the triggers directly.

CREATE TRIGGER prevent_audit_update
BEFORE UPDATE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'audit_log is append-only');
END;

CREATE TRIGGER prevent_audit_delete
BEFORE DELETE ON audit_log
BEGIN
    SELECT RAISE(ABORT, 'audit_log is append-only');
END;

-- Foreign-key and frequently queried column indexes.

CREATE INDEX idx_user_sessions_user
    ON user_sessions(user_id);

CREATE INDEX idx_assessments_created_by
    ON assessments(created_by);

CREATE INDEX idx_assessments_status
    ON assessments(status);

CREATE INDEX idx_test_runs_assessment
    ON test_runs(assessment_id);

CREATE INDEX idx_test_runs_test_case
    ON test_runs(test_case_id);

CREATE INDEX idx_findings_test_run
    ON findings(test_run_id);

CREATE INDEX idx_findings_severity
    ON findings(severity);

CREATE INDEX idx_evidence_test_run
    ON evidence(test_run_id);

CREATE INDEX idx_evidence_finding
    ON evidence(finding_id);

CREATE INDEX idx_security_events_created
    ON security_events(created_at);

CREATE INDEX idx_audit_log_created
    ON audit_log(created_at);

PRAGMA user_version = 1;